import{_ as t,o as i,c as r,a4 as o}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0001 — Licence open source du Core","description":"Extrait de docs/adr/0001-licence-apache-2-0.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0001 — Licence open source du Core","description":"Extrait de docs/adr/0001-licence-apache-2-0.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0001-licence-apache-2-0.md","filePath":"developpeurs/adr/0001-licence-apache-2-0.md"}'),n={name:"developpeurs/adr/0001-licence-apache-2-0.md"};function a(s,e,c,l,u,d){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0001--licence-open-source-du-core" tabindex="-1">ADR-0001 — Licence open source du Core <a class="header-anchor" href="#adr-0001--licence-open-source-du-core" aria-label="Permalink to &quot;ADR-0001 — Licence open source du Core {#adr-0001--licence-open-source-du-core}&quot;">​</a></h1><p><strong>Date :</strong> 19 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1, point ouvert §17 #1 ; plan d&#39;action agile §3.1.bis</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC v1.1 laisse la licence open source du Core « à déterminer », tout en soulignant que ce choix conditionne le modèle économique, la contribution externe et la possibilité d&#39;une édition Enterprise (§54 de la v1.0, non détaillée ici). Le CDC est explicite sur l&#39;urgence de la décision : <em>« à trancher avant la première publication publique, pas après : rétro-changer une licence sur un dépôt public est très difficile. »</em></p><p>Le positionnement produit retenu (ADR-0005) est « généraliste avec verticale publique forte », ce qui suppose un modèle économique à terme fondé au moins en partie sur une édition Enterprise ou des services, sans pour autant fermer le Core.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p>Le Core de Teuthis-CMS est publié sous <strong>Apache License 2.0</strong>.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>MIT</strong></td><td>Permissive comme Apache-2.0, mais sans clause de brevet explicite. Écartée car la couche IA (Provider Manager, Model Registry) touche à des mécanismes potentiellement brevetables chez certains fournisseurs cloud ; la clause de brevet d&#39;Apache-2.0 protège les contributeurs et les utilisateurs sans coût additionnel.</td></tr><tr><td><strong>AGPL-3.0</strong></td><td>Copyleft fort, empêcherait un hébergeur tiers de proposer le CMS en SaaS sans republier ses modifications. Écartée car elle freine la contribution d&#39;entreprises et complique la construction d&#39;une édition Enterprise propriétaire au-dessus du Core — ce qui contredit l&#39;ambition « Application Platform » du CDC.</td></tr><tr><td><strong>Business Source License (BSL)</strong></td><td>Protège davantage le modèle commercial initial mais n&#39;est pas reconnue comme « open source » au sens strict par l&#39;OSI, ce qui contredit directement le principe n°3 du CDC (« Open source »).</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Adoption et contribution externes facilitées — c&#39;est actuellement la licence dominante des projets d&#39;infrastructure open source à vocation commerciale (modèle « open core »).</li><li>Clause de brevet explicite : protège le projet et ses utilisateurs si un contributeur ou un fournisseur IA détient des brevets pertinents.</li><li>Compatible avec la quasi-totalité des écosystèmes Python et JavaScript utilisés par la stack (FastAPI, Nuxt).</li><li>Une édition Enterprise peut être construite comme un layer séparé, propriétaire, sans conflit de licence avec le Core.</li></ul><p><strong>Négatives</strong></p><ul><li>N&#39;empêche pas un tiers de proposer une offre SaaS concurrente basée sur le Core sans contribuer en retour — risque assumé, cohérent avec le choix de maximiser l&#39;adoption plutôt que de se protéger par le copyleft.</li><li>Le fichier <code>LICENSE</code> du dépôt était déjà en Apache-2.0 au moment de cette décision — aucune migration nécessaire.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] <code>LICENSE</code> du dépôt vérifié conforme (Apache-2.0 déjà en place).</li><li>[ ] Documenter la stratégie de licence pour une éventuelle édition Enterprise (hors périmètre de cet ADR).</li></ul>',16)])])}const h=t(n,[["render",a]]);export{m as __pageData,h as default};
